pointLocator.script:
var etd = [];

for (ndet = 1; ndet <= 8; ndet++) {
    if(typeof this['avgSpeedKph_'+ndet] != 'undefined'){
        var det = new Object();

        det.timestamp = this['beginTs_'+ndet].value;
        det.integration_period = this['durationS_'+ndet].value/60;
        det.current_direction = true;
        det.n_vehicles = this['vehicleCounter_'+ndet].value;
        det.occupancy = Math.round(this['occupationPct_'+ndet].value);
        det.congestion = Math.round(this['congestion_'+ndet].value);
        det.kamikaze = this['oppositeDirectionCounter_'+ndet].value > 0 ? true : false;
        det.average_speed = Math.round(this['avgSpeedKph_'+ndet].value);
        det.average_length = Math.round(this['avgLengthMm_'+ndet].value / 1000.0);
        det.gap = Math.round(this['intervehicleDistanceMm_'+ndet].value / 1000.0);
        det.headway = Math.round(this['intervehicleDistanceMm_'+ndet].value / 1000.0);
        det.fail_data = false;

        det.veh_speed_1 = Math.round(this['avgSpeedKph_class_0_' + ndet].value);
        det.veh_speed_2 = Math.round(this['avgSpeedKph_class_1_' + ndet].value);
        det.veh_speed_3 = Math.round(this['avgSpeedKph_class_2_' + ndet].value);
        det.veh_speed_4 = Math.round(this['avgSpeedKph_class_3_' + ndet].value);
        det.veh_speed_5 = Math.round(this['avgSpeedKph_class_4_' + ndet].value);
        det.veh_speed_6 = Math.round(this['avgSpeedKph_class_5_' + ndet].value);
        det.veh_speed_7 = Math.round(this['avgSpeedKph_class_6_' + ndet].value);
        det.veh_speed_8 = Math.round(this['avgSpeedKph_class_7_' + ndet].value);
        det.veh_speed_9 = Math.round(this['avgSpeedKph_class_8_' + ndet].value);

        det.veh_pa_1 = Math.round(this['classificationCounter_class_0_' + ndet].value);
        det.veh_pa_2 = Math.round(this['classificationCounter_class_1_' + ndet].value);
        det.veh_pa_3 = Math.round(this['classificationCounter_class_2_' + ndet].value);
        det.veh_pa_4 = Math.round(this['classificationCounter_class_3_' + ndet].value);
        det.veh_pa_5 = Math.round(this['classificationCounter_class_4_' + ndet].value);
        det.veh_pa_6 = Math.round(this['classificationCounter_class_5_' + ndet].value);
        det.veh_pa_7 = Math.round(this['classificationCounter_class_6_' + ndet].value);
        det.veh_pa_8 = Math.round(this['classificationCounter_class_7_' + ndet].value);
        det.veh_pa_9 = Math.round(this['classificationCounter_class_8_' + ndet].value);


        etd.push(det);
    }
}

var jsonString = JSON.stringify(etd);
return jsonString;
